  Hypothesis SPLO : stack_max_size <= usp.
  Hypothesis IMGHI : usp + Z.of_nat (length (entry_stack_image a_phdrs sp argv envp uid hw draw)) <= 2^64.
  Hypothesis SP16 : usp mod 16 = 0.
  Hypothesis VARGV : valid_argv argv.
